        print(f"First item type: {type(sections[0])}")
        print(f"First item: {sections[0]}")
elif isinstance(sections, dict):
    print(f"Keys: {sections.keys()}")
    print(f"First 500 chars: {str(sections)[:500]}")
else:
    print(f"Value: {sections}")
